// GENERATED by scripts/convert-deck-content.mjs from
// docs/content-drafts/card-meanings-draft.md — do not hand-edit.
// Re-run the script to regenerate after the draft changes.
import type { CardMeaning } from "./types";

export const CARD_MEANINGS: CardMeaning[] = [
  { id: 1, meaning: "News arriving, and the speed at which it arrives. The Rider is movement toward the querent from outside — a message, a visitor, a development that has been travelling and is now close. Where the Letter is the document, the Rider is the delivery: the fact of something coming, more than its contents. It carries a sense of imminence rather than distance. In older readings it also stands for a young man, particularly one who is active, mobile, or peripheral to the situation rather than settled inside it.\n\nThe tone is bright but light. The Rider brings, it does not decide. It says something is on its way; it says very little about whether that thing is welcome.", beside: "Usually the modifier rather than the subject. It makes its neighbour faster, nearer, or newly announced — Rider + Ring is news of an agreement, Rider + Coffin is news of an ending. When it follows rather than leads, it points to something moving away from the querent instead of toward them." },
  { id: 2, meaning: "Small good fortune, and the shortness of it. The Clover is a piece of luck that is real but minor and does not last — a break in the weather, a small opportunity, a problem that resolves more easily than expected. Its defining quality is not the good but the brevity. Traditional readings stress that Clover luck must be used quickly, because it does not wait.\n\nThe tone is genuinely light, and it is one of the few cards that lifts almost anything next to it. But it never promises scale. A Clover outcome is a good afternoon, not a good year, and reading it as more than that is one of the more common beginner errors.", beside: "Works as a modifier, softening or brightening the card it sits with, and shortening it. Clover + Mice is a small loss that passes. Clover + Ring is a lucky agreement, or a short one. Beside heavy cards it does not remove the weight; it makes it briefer." },
  { id: 3, meaning: "Distance, travel, and things that come from far away. The Ship is journeying — literal travel, foreign places, imports and exports, people abroad — and also longing, the pull toward something not here. It carries a sense of slow, continuous motion rather than the Rider's arrival. Where the Rider has nearly reached you, the Ship is still crossing.\n\nTraditionally it also touches on trade and commerce, and on movement of goods or money over distance.\n\nThe tone is neutral and open. A Ship is not good or bad; it describes range and direction. Read alone it tends to say not here and not yet.", beside: "Often the subject when travel is the question, and a modifier otherwise, where it pushes its neighbour outward — making it distant, foreign, or in transit. Ship + House is a home elsewhere, or a move. Ship + Heart is affection at a distance. It lengthens timelines rather than shortening them." },
  { id: 4, meaning: "Home, family, and the domestic sphere. The House is where the querent lives and who lives there — the household as a unit, its stability, its property, its inherited patterns. It also carries the sense of security and shelter more broadly: the things a person has built that they can return to.\n\nBy extension it stands for real estate and for family lines, including the ways a family's habits repeat across generations.\n\nThe tone is warm and settled, but not passive. The House is one of the more stable cards in the deck, and it tends to anchor whatever is near it.", beside: "Usually the noun. Cards next to it describe the household's condition rather than replacing it — Clouds + House is an unsettled home, Fox + House is something dishonest close to home. When it modifies, it makes its neighbour domestic or familial: House + Ring is a marriage read through the family rather than the couple." },
  { id: 5, meaning: "Health, growth, and the long time such things take. The Tree is the body and its condition, and also anything that develops slowly by its own nature — roots, lineage, the deep and unhurried. It is the deck's principal health card, though it says nothing on its own about whether health is good or poor.\n\nIt also carries spiritual and ancestral weight in the tradition: what is inherited, what runs deep, what cannot be rushed.\n\nThe tone is neutral and patient. The Tree resists speed. Where it appears, things take longer than the querent would like, and this is a feature of the matter rather than an obstruction.", beside: "Frequently the subject in health questions. As a modifier it slows and deepens — Tree + Heart is a bond with roots, Tree + Mice is something draining over time. Read with the Sun or Bouquet it leans toward good health; with Clouds, Mice, or Cross, toward a condition that needs attention." },
  { id: 6, meaning: "Confusion, doubt, and things not yet clear. The Clouds describe a situation the querent cannot see through — hidden information, mixed signals, a mood that has settled over something. It is not deception, which belongs to the Fox and the Snake; it is obscurity, whether or not anyone intends it.\n\nThe traditional deck often shows the card with a dark side and a light side, and many readers use its orientation to see which way the confusion is moving. If your deck marks this, the darker end indicates where the trouble sits.\n\nThe tone is uneasy and unresolved rather than actively bad. Clouds do not decide anything; they prevent you from seeing what has been decided.", beside: "Almost always a modifier. It clouds its neighbour — Clouds + Ring is an unclear agreement, Clouds + Man is a man whose intentions are not legible. It rarely stands as the subject unless the question is specifically about uncertainty itself." },
  { id: 7, meaning: "Complication, and the person or motive behind it. The Snake is the winding path — a matter that will not go straight, a difficulty that comes from someone else's interests rather than from circumstance. Traditionally it also stands for a woman close to the situation whose involvement is not straightforward, though this reading has been used carelessly enough that it deserves care.\n\nIt carries the sense of something coiled: pressure, entanglement, a route that doubles back.\n\nThe tone is difficult but not catastrophic. The Snake complicates; it does not end. It is worth separating from the Fox — the Fox is cunning and self-serving, the Snake is convoluted and entangling, and they are not the same problem.", beside: "Usually the modifier, twisting its neighbour into something complicated. Snake + Ring is an entangled agreement. Snake + Letter is a message that is not what it seems. Beside person cards it points to influence from outside." },
  { id: 8, meaning: "An ending, and the emptiness immediately after it. The Coffin is a matter concluded — something finished, closed, or set down. It is the deck's clearest card of termination, and in the tradition it also touches on illness, loss, and grief.\n\nIt should be read as an ending rather than a death. Most Coffins in most readings are jobs ending, relationships closing, phases finishing. Treating the card as literal mortality is both inaccurate and, in a reading for someone anxious, unkind.\n\nThe tone is heavy and still. The Coffin does not move. What distinguishes it from the Scythe is speed and agency: the Scythe cuts, the Coffin has already ended.", beside: "Often the subject. When it modifies, it closes its neighbour — Coffin + Ring is an agreement ended, Coffin + Mice is a loss that has run its course. Beside Tree it warrants care in health questions and should be read conservatively." },
  { id: 9, meaning: "Pleasure, welcome, and things offered gladly. The Bouquet is a gift, an invitation, a kindness — something given rather than earned. It also stands for beauty, charm, and social grace, and for the pleasant surface of things.\n\nUnlike the Clover, its good is not about luck but about goodwill: someone is being generous, or something is being made attractive.\n\nThe tone is bright and warm, and it is one of the deck's most reliably positive cards. Its one caution is that it describes the pleasant appearance of a thing, which is not always the whole of it — a Bouquet beside a difficult card can indicate something unwelcome, well presented.", beside: "Usually the modifier. It sweetens and beautifies — Bouquet + Letter is a welcome message, Bouquet + Woman is a woman who is charming or well regarded. Beside Fox or Snake, read the charm as surface rather than substance." },
  { id: 10, meaning: "A sudden cut. The Scythe is decisive, fast, and often unilateral — a decision made, a tie severed, something removed without negotiation. It is the card of the abrupt, and its defining quality is speed rather than severity.\n\nTraditionally it also carries a warning of accident or injury, particularly beside health cards, and many readers pay attention to which way the blade points as an indicator of what is being cut.\n\nThe tone is sharp and unsentimental. Unlike the Coffin, the Scythe has agency: something or someone is doing the cutting. It can be constructive — a clean break, a decision finally made — and reading it as purely destructive misses half its use.", beside: "Usually the modifier, cutting its neighbour. Scythe + Ring is an agreement broken. Scythe + Clouds is confusion suddenly cleared. It accelerates everything near it." },
  { id: 11, meaning: "Conflict and repetition. The Whip is argument, friction, and things that recur — a quarrel returned to, a pattern repeating, a physical or verbal back-and-forth. Its motion is rhythmic: whatever it touches happens more than once.\n\nThe tradition also gives it physical exertion and, in some lines, physical intimacy — the card covers a range of repeated bodily activity, and context does the work of distinguishing.\n\nThe tone is abrasive but active. The Whip is not despair; it is friction, and friction implies both parties are still engaged. It is often more workable than the flatness of the Cross or the stillness of the Coffin.", beside: "A modifier that adds conflict, repetition, or intensity. Whip + Heart is a relationship with recurring arguments. Whip + Letter is correspondence going back and forth. Where it appears, look for what is happening again." },
  { id: 12, meaning: "Talk, and the nervousness in it. The Birds are conversation — phone calls, chatter, gossip, negotiations, two people talking. The card is often read as anxiety as well, the mental fluttering that accompanies too much discussion.\n\nBecause the traditional image shows two birds, the card frequently indicates a pair: two people, two calls, a short duplication.\n\nThe tone is restless and light. The Birds are busy rather than heavy. Their difficulty is agitation, not damage.", beside: "Usually the modifier, making its neighbour verbal or anxious. Birds + Ring is a negotiation. Birds + House is talk within the family. Distinguish carefully from the Letter, which is written and formal, where the Birds are spoken and informal." },
  { id: 13, meaning: "Something new, small, and inexperienced. The Child is a beginning — a fresh start, an early stage, something at the outset of its life. It also carries innocence and naivety, and by extension the smallness or newness of whatever it touches.\n\nLiterally it can mean a child, a pregnancy, or a young person, though the card should not be read as pregnancy on its own without clear support.\n\nThe tone is fresh and gentle, and mostly light, though the naivety can cut both ways — a Child is trusting, which is sometimes a liability.", beside: "Usually the modifier. It makes its neighbour new, small, or immature — Child + Ring is a young commitment, Child + Fox is naive trust misplaced. It shrinks whatever it modifies, which can be a relief beside heavy cards and a limitation beside good ones." },
  { id: 14, meaning: "Cunning, self-interest, and things that serve someone else's purpose. The Fox is the deck's card of caution: something here is not straightforwardly what it claims to be, and there is an agenda under it. It covers deception, but also skilled self-preservation — the Fox is competent, not merely dishonest.\n\nThe tradition also connects it to employment and daily work, which sits oddly beside its trickery until you notice that both are about doing what is necessary to survive.\n\nThe tone is wary. The Fox rarely announces itself, and its warning is usually to look again rather than to withdraw.", beside: "Almost always the modifier, and one of the deck's strongest. It casts suspicion on its neighbour — Fox + Ring is an agreement with something wrong in it, Fox + Letter is a message that misleads. Beside the Bouquet or the Heart, read for charm that is being used." },
  { id: 15, meaning: "Strength, and the person or resource that holds it. The Bear is power — physical strength, financial weight, authority, and the capacity to protect. Traditionally it stands for a person of influence in the querent's life, often older, and often maternal or managerial: a boss, a mother, someone whose approval matters.\n\nIt also covers money in the sense of reserves rather than transactions — what is held, not what moves.\n\nThe tone is solid and largely protective, though the same weight can be overbearing. A Bear that supports and a Bear that dominates are the same card read in different contexts.", beside: "Can be either subject or modifier. As a modifier it makes its neighbour larger, stronger, or more forceful — Bear + Mice is a substantial loss, Bear + Heart is a strong attachment. Beside person cards, look for who holds the power." },
  { id: 16, meaning: "Clarity, direction, and reach. The Star is guidance — knowing where you are going, and being visible while you go. It covers hope, clear thinking, and in the modern tradition, wide exposure: broadcast, reputation, being seen at scale.\n\nIt also carries a scattered quality in some readings, from the many stars in the image: something spread widely rather than concentrated.\n\nThe tone is bright and calm — clearer and cooler than the Sun's warmth. Where the Sun is success and vitality, the Star is orientation. It tells you the way rather than telling you it went well.", beside: "Usually the modifier, clarifying and expanding its neighbour. Star + Clouds is confusion resolving. Star + Letter is a message widely seen. Beside difficult cards it offers direction rather than rescue." },
  { id: 17, meaning: "Change, particularly change of place or form. The Stork is movement from one state to another — relocation, a shift in circumstances, a transformation of something that already exists. Unlike the Child's fresh start, the Stork changes a thing that is already there.\n\nIts migratory nature gives it a cyclical quality, and traditionally it also touches on pregnancy and family growth, though again this needs support before it should be read literally.\n\nThe tone is hopeful and mobile. Stork change is usually improvement, or at least intended as such.", beside: "Usually the modifier, indicating that its neighbour is shifting. Stork + House is a move. Stork + Fox is a change in work. Beside static cards like the Mountain or Anchor, look at which is stronger — the change or the thing resisting it." },
  { id: 18, meaning: "Loyalty, friendship, and steady presence. The Dog is a friend — someone reliable, familiar, and on the querent's side. It also stands for trust itself, and for the quality of dependability wherever it appears.\n\nIts constancy is its whole meaning. A Dog does not surprise you.\n\nThe tone is warm and safe. It is one of the deck's most straightforwardly kind cards, and the tradition offers few cautions about it beyond the observation that loyalty can be given to the wrong person — which shows in the neighbours, not in the Dog.", beside: "Often the subject when the question concerns a friend, and a modifier otherwise, where it makes its neighbour trustworthy or familiar. Dog + Letter is a message from a friend. Dog + Fox is loyalty being taken advantage of, and is worth reading carefully." },
  { id: 19, meaning: "Institutions, separation, and the long view. The Tower is formal structure — government, corporations, hospitals, universities, anything official and impersonal. It also carries solitude and distance: standing apart, whether by choice or circumstance.\n\nThe two senses connect through height. A tower sees far and is hard to reach, and both the authority and the isolation follow from that.\n\nThe tone is cool and neutral. The Tower is neither kind nor unkind; it is impersonal, and its difficulty is usually distance rather than harm.", beside: "Can be subject or modifier. As a modifier it makes its neighbour official, formal, or separate — Tower + Letter is an official document, Tower + Heart is emotional distance. Beside Garden it makes a useful contrast: the Tower is alone, the Garden is among people." },
  { id: 20, meaning: "The public, and the querent's place in it. The Garden is where people gather — events, networks, social circles, the community and the public eye. It covers meeting others, being among them, and anything that happens in the open rather than in private.\n\nIt also carries a lighter social sense: enjoyment in company, the pleasure of being out.\n\nThe tone is open and mildly positive. The Garden's caution is exposure — what happens here is seen, which matters when the neighbouring cards are ones the querent would rather keep quiet.", beside: "Usually the modifier, making its neighbour public or social. Garden + Letter is a public announcement. Garden + Fox is dishonesty in a social circle. Beside Tower, read as public versus institutional, or public versus alone." },
  { id: 21, meaning: "An obstacle, and the delay it causes. The Mountain is a genuine blockage — something large, immovable, and slow to pass. It stands in the way, and it does not care about the querent's timeline.\n\nIt also carries coldness and distance in some readings: an obstacle can be a person's remoteness as much as a circumstance.\n\nThe tone is heavy and static. The Mountain is not malicious; it is simply there. Its most useful feature is that it can be gone around, and readings often point to the route rather than to removal.", beside: "A strong modifier that blocks or delays its neighbour. Mountain + Letter is a message not arriving. Mountain + Heart is a blocked or distant affection. Beside movement cards — Rider, Stork, Ship — it is the thing holding them up." },
  { id: 22, meaning: "Choice, and the multiplication that comes with it. The Crossroads is a decision point with more than one viable route, and the card describes the moment of choosing rather than the outcome. Because it forks, it also indicates plurality — two of something, several options, alternatives running in parallel.\n\nThe tradition does not usually mark one path as correct. That work belongs to the surrounding cards.\n\nThe tone is neutral and slightly unsettled. A Crossroads is not a problem; it is an open question, and its discomfort is the discomfort of not having decided yet.", beside: "Usually the modifier, indicating that its neighbour comes in more than one form or is subject to a decision. Crossroads + Ring is a choice about a commitment, or more than one agreement. Beside Clouds it points to a decision made without enough information." },
  { id: 23, meaning: "Loss by attrition. The Mice describe something being worn away — stress eating at a person, money leaking, a possession disappearing, health gradually depleted. The card's defining quality is gradualness. Nothing is taken at once; it goes small piece by small piece.\n\nIt also carries anxiety and the physical toll of it, and by extension things that are damaged, dirty, or in disrepair.\n\nThe tone is uneasy and depleting. The Mice are more tiring than dramatic, and their danger is that they are easy to ignore until a great deal has gone.", beside: "Usually the modifier, diminishing its neighbour. Mice + Ring is a commitment being eroded. Mice + Bear is money draining. Beside good cards it does not cancel them — it reduces them, which is a different and often more accurate reading." },
  { id: 24, meaning: "Affection. The Heart is love in its broad sense — romantic attachment, warmth, care, the emotional dimension of any matter. It is the card that tells you feeling is involved, without specifying what kind of relationship holds it.\n\nIt also stands for generosity and kindness, and for the emotional truth underneath a situation's practical surface.\n\nThe tone is warm and open. The Heart is largely uncomplicated, and most of its difficulty comes from neighbours rather than from itself.", beside: "Often the subject in relationship questions. As a modifier it makes its neighbour emotional or beloved — Heart + Letter is a message with feeling in it, Heart + Fox is affection being used. Read alongside the Ring for the useful distinction between feeling and commitment, which are not the same and do not always travel together." },
  { id: 25, meaning: "Commitment and the form it takes. The Ring is an agreement — marriage, partnership, contract, or any binding arrangement. Its circularity also gives it repetition and continuity: something ongoing, something that comes back around.\n\nCrucially, the Ring says nothing about affection. A Ring is a bond, and bonds exist without warmth as often as with it.\n\nThe tone is neutral and formal. Whether a Ring is good news depends entirely on what it is a commitment to, which is the neighbours' job to say.", beside: "Often the subject. As a modifier it binds or formalises its neighbour — Ring + Fox is an agreement with something dishonest in it, Ring + Coffin is a commitment ended. Read against the Heart: Heart + Ring is a loving commitment, Ring alone beside difficult cards may be a bond someone is stuck in." },
  { id: 26, meaning: "What is not yet known. The Book is a secret, a matter still closed, or knowledge the querent does not have — and, in its other face, learning, study, and formal education. The two senses are the same card seen from either side of the cover.\n\nTraditionally readers pay attention to whether the book in the image is open or closed, taking an open Book as knowledge available and a closed one as knowledge withheld.\n\nThe tone is neutral and reserved. The Book does not say the secret is bad; it says there is something you have not been told.", beside: "Usually the modifier, making its neighbour hidden or academic. Book + Heart is a secret affection. Book + Fox is deception concealed. Distinguish from Clouds: Clouds is confusion, Book is information deliberately not shared." },
  { id: 27, meaning: "Written communication, and the document itself. The Letter is anything on paper or screen — messages, emails, contracts, results, paperwork, records. Where the Rider is the arrival of news, the Letter is the news in written form.\n\nIt also stands for the formal or recorded quality of a matter: something set down, and therefore something that can be referred back to.\n\nThe tone is neutral. The Letter is a container, and its contents come from the cards around it.", beside: "Almost always the modifier, making its neighbour written or documented. Letter + Ring is a written contract. Letter + Coffin is a formal termination. Distinguish carefully from the Birds, which is speech, and the Rider, which is arrival rather than content." },
  { id: 28, meaning: "A man in the querent's situation, or the querent himself. The Man is the deck's principal significator for an adult male — a partner, a colleague, a figure the reading concerns. In a reading for a man, it usually stands for the querent.\n\nIt carries no inherent quality of its own. Everything about him — his temperament, his role, his intentions — comes from the cards nearby.\n\nThe tone is entirely neutral. This is a placeholder for a person, and reading character into the card itself is a mistake.", beside: "Almost always the subject. The neighbours describe him: Man + Fox is a man not being straight, Man + Bear is a man with authority, Man + Coffin is a man at an ending. Which card sits closest usually says the most." },
  { id: 29, meaning: "A woman in the querent's situation, or the querent herself. The Woman is the deck's principal significator for an adult female, and in a reading for a woman it typically stands for the querent.\n\nLike the Man, it has no character of its own. It marks a person's presence in the reading and waits for the neighbours to describe her.\n\nThe tone is entirely neutral. It is worth saying plainly that the tradition sometimes attaches unflattering assumptions to this card via the Snake; those readings are cultural residue rather than card meaning, and they can be left behind without loss.", beside: "Almost always the subject. The neighbours describe her: Woman + Heart is a woman who cares, Woman + Mountain is a woman who is blocked or distant. In readings involving both significators, the distance between Man and Woman is often more informative than either card alone." },
  { id: 30, meaning: "Maturity, and what settles with it. The Lily covers age, experience, calm, and long-established things — an older person, a seasoned relationship, a peace that has been arrived at rather than granted. It also carries virtue and propriety in the older tradition, and sexuality in another line of reading, which sit less oddly together than they first appear: both concern what is private and adult.\n\nThe tone is cool, quiet, and mostly favourable. The Lily is slow and does not force anything.", beside: "Can be subject or modifier. As a modifier it ages and calms its neighbour — Lily + Ring is a long-established commitment, Lily + Heart is a mature or settled affection. Beside Child it marks a clear contrast in age or stage." },
  { id: 31, meaning: "Success, energy, and things going well. The Sun is the deck's strongest positive card — vitality, achievement, warmth, and clarity of a confident rather than directional kind. Where the Star orients, the Sun powers.\n\nIt also carries visibility in the plain sense: things brought into the light and seen clearly.\n\nThe tone is bright and strong, and it lifts nearly everything around it. Its one caution is intensity — a Sun can be too much of a good thing, and beside cards of excess it is worth noticing.", beside: "Usually the modifier, brightening and energising its neighbour. Sun + Ring is a successful agreement. Sun + Clouds is confusion burning off. Beside difficult cards it genuinely improves them, more than most cards in the deck can." },
  { id: 32, meaning: "Feeling, recognition, and the inner life. The Moon covers emotion in a deeper sense than the Heart's warmth — mood, intuition, the unconscious — and, in a second and equally traditional line, honour and public recognition: reputation, awards, being acknowledged.\n\nIt also governs cycles and months, and is one of the deck's more commonly used timing cards.\n\nThe tone is soft and shifting. The Moon changes, and readings involving it often describe something that will not hold still.", beside: "Usually the modifier, adding emotional weight or recognition. Moon + Heart is deep feeling. Moon + Garden is public recognition. Which of its two senses applies is decided by the question, and it is worth deciding before you read rather than after." },
  { id: 33, meaning: "Certainty and access. The Key is the card of yes — something opening, a solution found, a matter confirmed. It marks importance too: what the Key touches is significant to the reading, not incidental.\n\nIts opening quality works both ways. A Key can unlock what was shut, and it can also mark something being formally opened that the querent might have preferred closed.\n\nThe tone is positive and definite. The Key is one of the few cards that offers something close to confirmation, and it is heavily relied on in yes-or-no work for that reason.", beside: "Usually the modifier, confirming or unlocking its neighbour. Key + Ring is an agreement confirmed. Key + Book is a secret revealed. Beside Mountain it often indicates the way around the obstacle." },
  { id: 34, meaning: "Money in motion, and abundance. The Fish is income, business, transactions, and flow — money moving rather than money held, which is the Bear's territory. It also carries plenty and multiplicity: many of something, more than expected.\n\nIts independence is worth noting. The Fish is often connected to self-employment and to working for oneself.\n\nThe tone is positive and fluid. The Fish's caution is that flow runs both ways, and beside Mice or Scythe it describes money leaving as readily as arriving.", beside: "Can be subject or modifier. As a modifier it makes its neighbour financial or plentiful — Fish + Letter is an invoice or a financial document, Fish + Fox is dishonesty around money. Read against the Bear for the distinction between reserves and flow." },
  { id: 35, meaning: "Stability and things that hold. The Anchor is what stays — persistence, a long-term situation, work that continues, a commitment that has settled into place. Traditionally it is strongly associated with employment and with the parts of life that do not change quickly.\n\nIts other face is being stuck. The same weight that holds a thing steady prevents it from moving, and which reading applies depends on whether the querent wants to stay.\n\nThe tone is steady and grounded, generally favourable when stability is wanted and constraining when it is not.", beside: "Usually the modifier, making its neighbour lasting or fixed. Anchor + Heart is enduring affection. Anchor + Mice is a slow drain that persists. Beside Stork or Ship, read the tension between what wants to move and what will not." },
  { id: 36, meaning: "Burden, and the sense that it must be carried. The Cross is difficulty of a particular kind — hardship, grief, obligation, something heavy that cannot simply be put down. It also carries faith, fate, and belief in the traditional reading, and the two senses share a root: both concern what a person accepts rather than chooses.\n\nThe tone is sombre. The Cross is the deck's card of suffering, and it should be delivered carefully, especially to someone already struggling.\n\nIt is also, importantly, finite. A Cross is borne and then it is over, and readings frequently show what comes after it.", beside: "Usually the modifier, weighting its neighbour with difficulty or significance. Cross + Ring is a burdensome commitment. Cross + Letter is hard news. Beside Sun, Star, or Key, look for what lightens it — those combinations are frequently about endurance leading somewhere." },
];
